CREATE OR REPLACE FUNCTION public.apply_directory_import(batch_id uuid,reverse_batch boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.directory_import_batches; r jsonb; new_id uuid; ids uuid[]:='{}'; c public.directory_categories; loc public.directory_locations; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO b FROM public.directory_import_batches WHERE id=batch_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Batch unavailable'; END IF;
IF reverse_batch THEN IF b.status<>'applied' THEN RAISE EXCEPTION 'Only applied batches can reverse'; END IF;
IF EXISTS(SELECT 1 FROM public.businesses x WHERE x.id=ANY(b.applied_ids) AND (x.updated_at>b.applied_at OR EXISTS(SELECT 1 FROM public.leads WHERE business_id=x.id) OR EXISTS(SELECT 1 FROM public.reviews WHERE business_id=x.id) OR EXISTS(SELECT 1 FROM public.business_offerings WHERE business_id=x.id) OR EXISTS(SELECT 1 FROM public.directory_redirects WHERE kind='business' AND (from_key=x.id::text OR to_key=x.id::text)))) THEN RAISE EXCEPTION 'Later edits or linked activity prevent reversal; review individually'; END IF;
UPDATE public.businesses SET archive_status=status,archived_at=now(),status='archived' WHERE id=ANY(b.applied_ids); UPDATE public.directory_import_batches SET status='reversed' WHERE id=batch_id;
ELSE IF b.status<>'staged' THEN RAISE EXCEPTION 'Batch already processed'; END IF; IF jsonb_array_length(b.rows)<1 OR jsonb_array_length(b.rows)>500 THEN RAISE EXCEPTION 'Invalid batch size'; END IF;
FOR r IN SELECT value FROM jsonb_array_elements(b.rows) LOOP
IF length(coalesce(r->>'name',''))<2 OR coalesce(r->>'phone','') !~ '^\+?[0-9 ()-]{10,20}$' OR length(coalesce(r->>'address',''))<1 OR length(coalesce(r->>'area',''))<1 OR coalesce(r->>'source_url','') !~ '^https?://' OR coalesce(r->>'website','') !~ '^https?://' OR public.obvious_placeholder(r->>'description') OR (coalesce(r->>'pincode','')<>'' AND r->>'pincode' !~ '^[1-9][0-9]{5}$') THEN RAISE EXCEPTION 'Invalid import row; publication blocked'; END IF;
SELECT * INTO c FROM public.directory_categories WHERE (slug=r->>'category' OR legacy_slug=r->>'category') AND active LIMIT 1; SELECT * INTO loc FROM public.directory_locations WHERE kind='city' AND name=r->>'city' AND active LIMIT 1; IF c.id IS NULL OR loc.id IS NULL THEN RAISE EXCEPTION 'Unknown category or city'; END IF;
IF EXISTS(SELECT 1 FROM public.directory_locations WHERE kind='city' AND name<>r->>'city' AND position(lower(name) in lower(r->>'address'))>0) THEN RAISE EXCEPTION 'Address conflicts with city'; END IF;
INSERT INTO public.businesses(owner_id,name,category,category_id,city,city_id,area,address,phone,pincode,website,description,status,hours,days_open) VALUES(auth.uid(),r->>'name',coalesce(nullif(c.legacy_slug,''),c.slug),c.id,r->>'city',loc.id,r->>'area',r->>'address',r->>'phone',coalesce(r->>'pincode',''),r->>'website',coalesce(r->>'description',''),'approved','','{}') RETURNING id INTO new_id;
INSERT INTO public.directory_staff_notes(business_id,note) VALUES(new_id,'CSV import: '||b.filename||'; source: '||(r->>'source_url')); ids:=array_append(ids,new_id);
END LOOP; UPDATE public.directory_import_batches SET status='applied',applied_ids=ids,applied_at=now() WHERE id=batch_id; END IF;
INSERT INTO public.directory_audit(entity_id,action,actor_id,note) VALUES(batch_id,CASE WHEN reverse_batch THEN 'import_reversed' ELSE 'import_approved' END,auth.uid(),b.filename); END $$;
GRANT EXECUTE ON FUNCTION public.apply_directory_import(uuid,boolean) TO authenticated; REVOKE EXECUTE ON FUNCTION public.apply_directory_import(uuid,boolean) FROM anon,PUBLIC;
CREATE OR REPLACE FUNCTION public.guard_location() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.directory_locations; BEGIN IF NEW.verified AND NEW.source_url !~ '^https?://' THEN RAISE EXCEPTION 'Verified locations require a source'; END IF; IF NEW.kind='pincode' AND NEW.name !~ '^[1-9][0-9]{5}$' THEN RAISE EXCEPTION 'Invalid pincode'; END IF; IF NEW.kind='city' AND NEW.parent_id IS NOT NULL THEN RAISE EXCEPTION 'City cannot have a parent'; END IF; IF NEW.parent_id IS NOT NULL THEN SELECT * INTO p FROM public.directory_locations WHERE id=NEW.parent_id; IF p.kind<>'city' THEN RAISE EXCEPTION 'Locality and pincode parent must be a city'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER location_guard BEFORE INSERT OR UPDATE ON public.directory_locations FOR EACH ROW EXECUTE FUNCTION public.guard_location();